css:
.thr {
	width: 72mm;
	font-family: Arial, Helvetica, "Liberation Sans", sans-serif;
	font-size: 9px;
	line-height: 1.25;
	color: #000;
	font-weight: bold;
}
.thr .c { text-align: center; }
.thr .r { text-align: right; }
.thr .l { text-align: left; }
.thr table { width: 100%; border-collapse: collapse; table-layout: fixed; }
.thr td { vertical-align: top; padding: 0; word-wrap: break-word; overflow-wrap: break-word; }
.thr .line { border-top: 1px dashed #000; margin: 2px 0; }
.thr .co { font-size: 14px; font-weight: bold; letter-spacing: 0.3px; }
.thr .draft { font-size: 9px; font-weight: bold; }
.thr .thanks { font-style: italic; font-size: 11px; margin-top: 2px; }

.thr table.hd td { width: 50%; }

.thr table.it td { line-height: 1.05; }
.thr table.it td.d { width: 46%; }
.thr table.it td.r { width: 18%; }
.thr table.it .hdr td { font-weight: bold; }
.thr table.it .sn { font-size: 7px; vertical-align: super; }
.thr table.it .s { font-size: 8px; }
.thr table.it td.desc { padding-bottom: 2px; }

.thr table.tot td.l { width: 40%; }
.thr table.tot td.lbl { text-align: right; width: 38%; }
.thr table.tot td.val { text-align: right; width: 22%; }
.thr table.tot .g td { font-weight: bold; font-size: 11px; padding-top: 1px; }

@media print {
	@page { size: 80mm auto; margin: 2mm; }
}

html:
{#- Draft thermal (80mm) receipt — mirrors the POS Thermal GST layout.
    Rendered from a transient Sales Invoice so GST/taxes/totals are real.
    Clearly marked DRAFT and NOT a tax invoice. -#}

{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
{%- set gstin = doc.company_gstin or company.gstin or "" -%}

{%- set item_racks = get_item_racks(doc.items) -%}
{%- set show_rack = item_racks | length > 0 -%}

{%- set addr_lines = [] -%}
{%- for l in (doc.company_address_display or "").replace("\n", "").split("<br>") -%}
    {%- set l = l | striptags | trim -%}
    {%- if l and l | lower != "india" -%}{%- set _ = addr_lines.append(l) -%}{%- endif -%}
{%- endfor -%}

{%- set gst_rows = [] -%}
{%- set tot = namespace(sgst=0, cgst=0, igst=0, cess=0, other=0) -%}
{%- for t in doc.taxes -%}
    {%- set head = ((t.account_head or "") ~ " " ~ (t.description or "")) | upper -%}
    {%- if "SGST" in head -%}
        {%- set _ = gst_rows.append(t) -%}{%- set tot.sgst = tot.sgst + (t.tax_amount or 0) -%}
    {%- elif "CGST" in head -%}
        {%- set _ = gst_rows.append(t) -%}{%- set tot.cgst = tot.cgst + (t.tax_amount or 0) -%}
    {%- elif "IGST" in head -%}
        {%- set _ = gst_rows.append(t) -%}{%- set tot.igst = tot.igst + (t.tax_amount or 0) -%}
    {%- elif "CESS" in head -%}
        {%- set _ = gst_rows.append(t) -%}{%- set tot.cess = tot.cess + (t.tax_amount or 0) -%}
    {%- else -%}
        {%- set tot.other = tot.other + (t.tax_amount or 0) -%}
    {%- endif -%}
{%- endfor -%}

{%- if not gst_rows -%}
    {%- for item in doc.items -%}
        {%- set tot.sgst = tot.sgst + (item.sgst_amount or 0) -%}
        {%- set tot.cgst = tot.cgst + (item.cgst_amount or 0) -%}
        {%- set tot.igst = tot.igst + (item.igst_amount or 0) -%}
    {%- endfor -%}
{%- endif -%}

<div class="thr">

<div class="c draft">*** DRAFT — NOT A TAX INVOICE ***</div>
<div class="line"></div>

<div class="c co">{{ (company.company_name or doc.company) | upper }}</div>
{%- for l in addr_lines %}
<div class="c">{{ l | upper }}</div>
{%- endfor %}
{%- if company.phone_no %}
<div class="c">Phone : {{ company.phone_no }}</div>
{%- endif %}
{%- if company.email %}
<div class="c">E-Mail : {{ company.email }}</div>
{%- endif %}
{%- if gstin %}
<div class="c">{{ gstin }}</div>
{%- endif %}

<div class="line"></div>

<table class="hd">
    <tr>
        <td>Customer:{{ doc.customer_name }}</td>
        <td class="r">Draft No. {{ doc.name }}</td>
    </tr>
    <tr>
        <td>SALESMAN : {% if doc.sales_team %}{{ doc.sales_team[0].sales_person }}{% endif %}</td>
        <td class="r">Date : {{ doc.get_formatted("posting_date") }}</td>
    </tr>
    <tr>
        <td>User&nbsp;&nbsp;&nbsp;: {{ (doc.owner or "").split("@")[0] | upper }}</td>
        <td class="r">Time : {{ (doc.posting_time | string)[:5] }}</td>
    </tr>
</table>

<div class="line"></div>

<table class="it">
    <tr class="hdr">
        <td class="d">Sn.Qty&nbsp;Code{% if show_rack %}&nbsp;[Rack]{% endif %}</td>
        <td class="r">MRP</td>
        <td class="r">Dis%</td>
        <td class="r">GST%</td>
    </tr>
    <tr class="hdr">
        <td class="d" colspan="2">&nbsp;&nbsp;&nbsp;Description</td>
        <td class="r">N.Rate</td>
        <td class="r">N.Amt</td>
    </tr>
</table>

<div class="line"></div>

{%- set q = namespace(qty=0, sub=0) -%}
{%- for item in doc.items -%}
    {%- set mrp = item.price_list_rate or item.rate or 0 -%}
    {%- set q.qty = q.qty + (item.qty or 0) -%}
    {%- set q.sub = q.sub + mrp * (item.qty or 0) -%}
    {%- set rack = item_racks.get(item.item_code) -%}

    {%- set dis = item.discount_percentage or 0 -%}
    {%- if not dis and item.discount_amount and mrp -%}
        {%- set dis = item.discount_amount * 100 / mrp -%}
    {%- endif -%}

    {%- set rates = json.loads(item.item_tax_rate or "{}") or {} -%}
    {%- set g = namespace(rate=0) -%}
    {%- if rates -%}
        {%- for t in gst_rows -%}
            {%- set g.rate = g.rate + (rates.get(t.account_head, t.rate) or 0) -%}
        {%- endfor -%}
    {%- endif -%}
    {%- if not g.rate -%}
        {%- set g.rate = (item.igst_rate or 0) + (item.cgst_rate or 0) + (item.sgst_rate or 0) -%}
    {%- endif -%}
    {%- if not g.rate -%}
        {%- for t in gst_rows -%}{%- set g.rate = g.rate + (t.rate or 0) -%}{%- endfor -%}
    {%- endif -%}

<table class="it">
    <tr>
        <td class="d"><span class="sn">{{ loop.index }}</span> {{ "%.2f" | format(item.qty or 0) }} {{ item.item_code }}{% if rack %} [{{ rack }}]{% endif %}</td>
        <td class="r">{{ "%.2f" | format(mrp) }}</td>
        <td class="r s">{{ "%.2f" | format(dis) }}</td>
        <td class="r s">{{ "%.2f" | format(g.rate) }}</td>
    </tr>
    <tr>
        <td class="d desc" colspan="2">{{ (item.item_name or "") | truncate(26, True, "") | upper }}</td>
        <td class="r">{{ "%.2f" | format(item.rate or 0) }}</td>
        <td class="r">{{ "%.2f" | format(item.amount or 0) }}</td>
    </tr>
</table>
{%- endfor -%}

<div class="line"></div>

<table class="tot">
    <tr>
        <td class="l">Item Qty:&nbsp;&nbsp;{{ "%g" | format(q.qty) }}</td>
        <td class="lbl">SUB TOTAL:</td>
        <td class="val">{{ "%.2f" | format(q.sub) }}</td>
    </tr>
    {%- if tot.sgst %}
    <tr><td></td><td class="lbl">SGST Amt:</td><td class="val">{{ "%.2f" | format(tot.sgst) }}</td></tr>
    {%- endif %}
    {%- if tot.cgst %}
    <tr><td></td><td class="lbl">CGST Amt:</td><td class="val">{{ "%.2f" | format(tot.cgst) }}</td></tr>
    {%- endif %}
    {%- if tot.igst %}
    <tr><td></td><td class="lbl">IGST Amt:</td><td class="val">{{ "%.2f" | format(tot.igst) }}</td></tr>
    {%- endif %}
    {%- if tot.cess %}
    <tr><td></td><td class="lbl">CESS Amt:</td><td class="val">{{ "%.2f" | format(tot.cess) }}</td></tr>
    {%- endif %}
    {%- if not (tot.sgst or tot.cgst or tot.igst) %}
    <tr><td></td><td class="lbl">GST Amt:</td><td class="val">0.00</td></tr>
    {%- endif %}
    <tr><td></td><td class="lbl">Round off:</td><td class="val">{{ "%.2f" | format(doc.rounding_adjustment or 0) }}</td></tr>
    <tr><td></td><td class="lbl">FREIGHT:</td><td class="val">{{ "%.2f" | format(tot.other) }}</td></tr>
    <tr class="g">
        <td></td>
        <td class="lbl">G.TOTAL :</td>
        <td class="val">{{ "%.2f" | format(doc.rounded_total or doc.grand_total or 0) }}</td>
    </tr>
</table>

<div class="line"></div>
<div>{{ doc.in_words }}</div>
<div class="line"></div>

<div>Terms &amp; Conditions :-</div>
<div>1.Goods once sold not be taken back &amp; no cash Refund.</div>
<div>2.no Gurantee for Colours &amp; Pillings.</div>
<div>E.&amp;.O.E&nbsp;&nbsp;&nbsp;&nbsp;For "{{ (company.company_name or doc.company) | upper }}"</div>
<div class="c draft">*** DRAFT COPY — NOT A TAX INVOICE ***</div>

</div>
